#!/usr/bin/env python3
"""Границы диапазона размера в ПРОЗЕ: одна форма на конструкцию (issue #319).

Английское `<Size> or larger/smaller` — одно выражение, а в русском корпусе оно жило
ЧЕТЫРЬМЯ формами сразу: «Большое или большее существо», «Большое или более крупное
существо», «размера Большой или больше» и «размера не больше Большого». Расщепление того
же класса, что вычищали #256 и #271, только в прозе: парсеры прозу не разбирают, и до этого
гейта его не ловило ничто.

Решение (`src/dnd/translate/logs/2026-09-09_prose_log.md`) — не одна форма, а ДВЕ, и выбор
между ними делает синтаксис, а не вкус:

* определение при существительном → согласованное прилагательное «больший / меньший»
  («Большое или большее существо»), размер — словарным термином с прописной, связка — со
  строчной (та же конвенция, что у шапок, #303/#256);
* сказуемое или оборот «размера X» → несклоняемое «или больше / или меньше»
  («существо размера Огромный или больше»).

Отсюда три запрета ниже. Описательные «более крупный / более маленький» запрещены как
ФОРМА ГРАНИЦЫ — но остаются законными для голого английского `larger` без размера рядом
(«более крупное существо» = `a larger creature`), и правило это различает: слева от «или»
обязан стоять размер.

Четвёртая проверка — количественная. Формы можно было бы вычистить и потеряв половину
границ по дороге, поэтому число RU-вхождений сверяется с числом EN-вхождений пофайлово:
это единственная проверка, которая заметит, что граница не переписана, а исчезла.

Запуск: python3 .github/scripts/test_prose_size_bounds.py
"""
import re
import sys
from pathlib import Path

SCRIPTS = Path(__file__).resolve().parent
ROOT = SCRIPTS.parents[1]
CORPUS = ROOT / "src" / "dnd"
sys.path.insert(0, str(SCRIPTS))
# Состав размеров — из таблицы форм гейтов шапок, а не четвёртым списком в репозитории.
# Копия уже успела разойтись с собственным описанием (ревью #322), и это ровно тот класс
# расхождения, ради которого таблица одна: заведись завтра седьмой размер — он войдёт сюда
# сам, а список пришлось бы вспомнить.
from statblock_terms import SIZE_FORMS  # noqa: E402

# Основа = мужская форма без окончания: «Крошечный» → «Крошечн». Окончание одно из трёх, и
# состав основ пришпилен самопроверкой ниже — правило вывода не должно молча ослабнуть.
SIZE_STEMS = tuple(re.sub(r"(?:ый|ой|ий)$", "", forms[0]) for forms in SIZE_FORMS.values())
# Альтернация основ в ОБОИХ регистрах: где регистр важен, проверка смотрит на первую букву
# отдельно — и это работает, только если строчная форма вообще может совпасть.
STEM_ALT = "|".join(f"[{s[0]}{s[0].lower()}]{s[1:]}" for s in SIZE_STEMS)
# Наречие «больше» подпадает под основу «Больш-», и без отсечки «на два размера больше или
# меньше вас» читалось бы как граница размера. «Меньше» в отсечку НЕ входит: основы «меньш-»
# среди размеров нет, ветка была бы инертной и объясняла бы несуществующий механизм.
SIZE = rf"(?![Бб]ольше\b)(?:{STEM_ALT})\w*"

# 1. Описательная форма границы: «<Размер> или более крупное». Союз «и» тоже ловим —
#    именно так была записана одна из находок #319 («Маленькие и более мелкие существа»).
DESCRIPTIVE = re.compile(
    rf"\b({SIZE})\s+(?:или|и)\s+((?:более|менее)\s+(?:крупн|мелк|маленьк)\w+)")
# 2. Оборот-перифраз: «размера не больше Большого» вместо «размера Большой или меньше».
PARAPHRASE = re.compile(
    rf"\bразмера\s+не\s+(?:больше|меньше)\s+({SIZE})")
# 3a. Регистр: размер в границе пишется словарным термином с прописной.
#     Основа «больш-» здесь ОБЯЗАНА быть, хотя и даёт омонимию с обычным прилагательным:
#     под ней 157 из 190 нижних границ, то есть та самая форма, которую канон объявляет
#     главной. Была исключена — и 84 границы регистром не проверялись вовсе, а комментарий
#     утверждал, что их ловит 3b (та работает только после слова «размера»); поймано
#     ревью #322. Неразмерные совпадения снимаются не регуляркой, а списком `NOT_A_SIZE`.
REGISTER_BOUND = re.compile(
    rf"(?<![\w-])({SIZE})\s+или\s+(?:больше\b|меньше\b|больш\w+|меньш\w+)")
# 3b. После «размера» слово-размер однозначно термин.
#     «на два размера больше» — не размер, а сравнение: отсекается тем же лукахедом SIZE.
REGISTER_AFTER = re.compile(rf"\bразмера\s+({SIZE})")

# Счётные формы: EN-выражение и его законные RU-соответствия (обе разрешённые формы).
# Регистр связки у EN не фиксирован НИ СВЕРХУ, НИ СНИЗУ. Прописная `Smaller` носителя имеет
# (`srd-5.2/en/07_Spells.md` — врезка `*Huge or Smaller Construct, Unaligned*`), а прописная
# `Larger` заведена впрок конвенцией #303: продукционный парсер её разбирает, гейты шапок
# держат фикстурами. Оставь здесь только строчную — первая же такая шапка, написанная строго
# по канону, дала бы ЛОЖНЫЙ красный на верном переводе, и штатного зелёного выхода не было бы
# (ревью #322).
EN_UPPER = re.compile(
    r"\b(?:Tiny|Small|Medium|Large|Huge|Gargantuan)(?:\s+size)?\s+or\s+(?:[Ll]arger|[Bb]igger)\b")
EN_LOWER = re.compile(
    r"\b(?:Tiny|Small|Medium|Large|Huge|Gargantuan)(?:\s+size)?\s+or\s+[Ss]maller\b")
RU_UPPER = re.compile(rf"\b({SIZE})\s+или\s+(?:больше\b|больш\w+|более\s+крупн\w+)")
RU_LOWER = re.compile(rf"\b({SIZE})\s+или\s+(?:меньше\b|меньш\w+|более\s+(?:мелк|маленьк)\w+)")

# Совпадения по ФОРМЕ, у которых размера нет. Ключ — путь от src/dnd, значение — фраза и
# поправка к счёту (Δверх, Δниз), которую эта фраза объясняет. Одна запись закрывает обе
# проверки сразу: и вычет из счёта, и слепое пятно регистра — потому что это одно и то же
# вхождение, и держать его в двух списках значило бы завести два места для расхождения.
#
# Список ЗАКРЫТЫЙ и сам проверяется на протухание: исчезнет фраза из главы — гейт скажет
# именно это, а не выдаст чужой диагноз («граница потеряна при переводе»).
NOT_A_SIZE = {
    "srd-5.1/ru/14_Monsters.md": ("представляя большую или меньшую угрозу", 0, 1),
}

failures = []
checks_run = 0


def excused_spans(text, phrase):
    """Промежутки текста, занятые неразмерной фразой из `NOT_A_SIZE`."""
    spans = []
    start = 0
    while phrase and (at := text.find(phrase, start)) >= 0:
        spans.append((at, at + len(phrase)))
        start = at + 1
    return spans


def scan(text, phrase=""):
    """Находки запретов: список (правило, фрагмент, смещение)."""
    hits = []
    for m in DESCRIPTIVE.finditer(text):
        hits.append(("описательная форма", m.group(0), m.start()))
    for m in PARAPHRASE.finditer(text):
        hits.append(("перифраз «не больше»", m.group(0), m.start()))
    # Регистр: размер в границе пишется словарным термином с прописной. Гвард по первой букве
    # — настоящая ветка, а не украшение: альтернация основ несёт оба регистра, и прописной
    # размер сюда доходит (проверено самопроверками «канон …» и мутацией `if True`).
    spans = excused_spans(text, phrase)
    for pattern, rule in ((REGISTER_BOUND, "строчный размер в границе"),
                          (REGISTER_AFTER, "строчный размер после «размера»")):
        for m in pattern.finditer(text):
            if not m.group(1)[0].islower():
                continue
            if any(lo <= m.start() < hi for lo, hi in spans):
                continue
            hits.append((rule, m.group(0), m.start()))
    return hits


# ── Самопроверки: правило проверяется на синтетике, а не на состоянии корпуса ────────────
def check(label, text, want, phrase=""):
    global checks_run
    checks_run += 1
    got = sorted(rule for rule, _, _ in scan(text, phrase))
    if got != sorted(want):
        failures.append(f"самопроверка «{label}»: сработало {got}, ожидалось {sorted(want)}")


check("канон: прилагательное", "Большое или большее существо получает преимущество.", [])
check("канон: наречие", "существо размера Огромный или больше.", [])
check("канон: нижняя граница", "Среднее или меньшее существо схвачено.", [])
check("описательная сверху", "Крошечное или более крупное существо касается области.", ["описательная форма"])
check("описательная снизу", "Среднее или более маленькое существо схвачено.", ["описательная форма"])
check("описательная через «и»", "Маленькие и более мелкие летающие существа.", ["описательная форма"])
check("голое «более крупное» — законно", "если в области находится более крупное существо.", [])
check("перифраз", "по существу размера не больше Большого.", ["перифраз «не больше»"])
check("строчный размер в границе", "если она огромная или больше.", ["строчный размер в границе"])
# Оба регистровых правила на одной фразе — так и должно быть: 3a ловит границу, 3b — слово
# после «размера». Пересечение не дефект, а следствие того, что 3a наконец знает «больш-».
check("строчный размер после «размера»", "объектов размера большой или меньше.",
      ["строчный размер после «размера»", "строчный размер в границе"])
check("прописной размер после «размера»", "объектов размера Большой или меньше.", [])
# Основа «больш-» — 157 из 190 нижних границ, и без неё регистровая проверка молчала на самой
# частой форме канона. Пара «строчная краснеет / прописная молчит» пришпилена отдельно.
check("строчный «больш-» в границе", "большое или большее существо схвачено.",
      ["строчный размер в границе"])
check("прописной «больш-» в границе", "Большое или большее существо схвачено.", [])
# Неразмерное совпадение снимается ТОЛЬКО названной фразой: без неё оно обязано краснеть,
# иначе список `NOT_A_SIZE` был бы декорацией.
check("«большую или меньшую угрозу» — с записью в NOT_A_SIZE",
      "представляя большую или меньшую угрозу, чем", [], "представляя большую или меньшую угрозу")
check("та же фраза без записи — находка", "представляя большую или меньшую угрозу, чем",
      ["строчный размер в границе"])
# Состав основ выводится из таблицы гейтов шапок — правило вывода пришпилено, иначе смена
# окончания в `SIZE_FORMS` молча выключила бы часть проверок.
checks_run += 1
if SIZE_STEMS != ("Крошечн", "Маленьк", "Средн", "Больш", "Огромн", "Громадн"):
    failures.append(f"самопроверка основ: из SIZE_FORMS вывелось {SIZE_STEMS}")

# Счёт: те же тексты, что и в корпусе, только синтетические.
def count_check(label, en, ru, want_up, want_dn):
    global checks_run
    checks_run += 1
    got = (len(EN_UPPER.findall(en)), len(RU_UPPER.findall(ru)),
           len(EN_LOWER.findall(en)), len(RU_LOWER.findall(ru)))
    if got != want_up + want_dn:
        failures.append(f"самопроверка счёта «{label}»: {got}, ожидалось {want_up + want_dn}")


count_check("пара сходится", "a Large or larger creature", "Большое или большее существо", (1, 1), (0, 0))
count_check("«Medium size or smaller» — тоже граница", "a stone object of Medium size or smaller",
            "каменный объект размера Средний или меньше", (0, 0), (1, 1))
count_check("граница пропала в переводе", "a Huge or smaller creature", "существо любого размера",
            (0, 0), (1, 0))
count_check("«20 by 20 ft. or larger» — не размер", "20 by 20 ft. or larger", "20 на 20 футов или больше",
            (0, 0), (0, 0))
count_check("«на два размера больше или меньше» — сравнение, не граница",
            "two sizes larger or smaller than you", "на два размера больше или меньше вас", (0, 0), (0, 0))
# Прописная связка есть у обеих границ: `Smaller` — живая (врезка Animate Objects), `Larger` —
# заведена впрок конвенцией #303. Шапка, написанная строго по канону, обязана СЧИТАТЬСЯ, а не
# давать ложный красный на верном переводе.
count_check("прописная связка в шапке — тоже граница",
            "> *Huge or Larger Construct, Unaligned*", "> *Огромный или больший Конструкт, без мировоззрения*",
            (1, 1), (0, 0))
count_check("прописная нижняя связка", "> *Huge or Smaller Construct, Unaligned*",
            "> *Огромный или меньший Конструкт, без мировоззрения*", (0, 0), (1, 1))

# ── Живой корпус ────────────────────────────────────────────────────────────────────────
if not CORPUS.is_dir():
    print(f"❌ Корпус не найден: {CORPUS}")
    sys.exit(1)

ru_docs = sorted(p for p in CORPUS.glob("srd-*/ru/**/*.md"))
if not ru_docs:
    failures.append(f"{CORPUS}: ни одной RU-главы не найдено — обход дерева сломан")

pairs = 0
for doc in ru_docs:
    rel = str(doc.relative_to(CORPUS))
    text = doc.read_text(encoding="utf-8")
    phrase, per_up, per_dn = NOT_A_SIZE.get(rel, ("", 0, 0))
    # Вычет считается по ФАКТИЧЕСКОМУ числу вхождений извиняемой фразы, а не по константе:
    # уйди фраза из главы — вычет уйдёт вместе с ней, и счёт сойдётся сам. Иначе остаток
    # уводил итог в отрицательное число вхождений («RU −1») и обвинял перевод в потере
    # границы, которой не было (ревью #322). Само протухание записи ловится ниже, отдельно.
    excused = len(excused_spans(text, phrase))
    # Номер строки — по СМЕЩЕНИЮ матча, а не поиском фрагмента: три одинаковых нарушения в
    # одной главе печатались одним и тем же номером, и автор чинил первое, получая то же
    # красное снова (ревью #322). Фрагмент, разорванный переносом строки, тем же поиском
    # давал номер 0.
    for rule, frag, pos in scan(text, phrase):
        failures.append(f"{rel}:{text.count(chr(10), 0, pos) + 1} — {rule}: «{frag}»")

    en_doc = CORPUS / rel.replace("/ru/", "/en/", 1)
    # Пропавшая EN-пара — не повод молча пропустить счётную половину: перенос или
    # переименование главы (делали #296 и #317) выключил бы её бесшумно, оставив следом лишь
    # число `pairs` в зелёной строке, которое никто не сверяет (ревью #322).
    if not en_doc.is_file():
        failures.append(f"{rel}: EN-пары нет — счёт границ не сверен")
        continue
    pairs += 1
    en_text = en_doc.read_text(encoding="utf-8")
    got_up = len(RU_UPPER.findall(text)) - per_up * excused
    got_dn = len(RU_LOWER.findall(text)) - per_dn * excused
    want_up, want_dn = len(EN_UPPER.findall(en_text)), len(EN_LOWER.findall(en_text))
    if (got_up, got_dn) != (want_up, want_dn):
        failures.append(
            f"{rel} — счёт границ разошёлся с оригиналом: верх EN {want_up} / RU {got_up}, "
            f"низ EN {want_dn} / RU {got_dn}")

# Запись, переставшая быть нужной, — тоже расхождение: молчащая через год читается как
# разрешение, которого никто не проверял. Ищем саму ФРАЗУ, а не файл: без неё вычет остаётся,
# и итог уходил бы отрицательным числом вхождений («RU −1») — диагноз чужой и пугающий.
for rel, (phrase, _, _) in NOT_A_SIZE.items():
    checks_run += 1
    doc = CORPUS / rel
    if not doc.is_file():
        failures.append(f"NOT_A_SIZE: {rel} — такого файла нет, запись протухла")
    elif phrase not in doc.read_text(encoding="utf-8"):
        failures.append(f"NOT_A_SIZE: «{phrase}» в {rel} больше нет — уберите запись, "
                        f"иначе вычет из счёта останется без своего вхождения")

if failures:
    print(f"❌ Границы диапазона размера в прозе ({len(failures)}):")
    for f in failures:
        print(f"  — {f}")
    if any(not f.startswith("самопроверка") for f in failures):
        print("  Канон: определение при существительном — «Большое или большее существо»;")
        print("  сказуемое и оборот «размера X» — «размера Огромный или больше».")
        print("  Решение: src/dnd/translate/logs/2026-09-09_prose_log.md")
    sys.exit(1)

print(f"✅ Границы размера в прозе: {len(ru_docs)} RU-глав, {pairs} пар сверено с оригиналом, "
      f"{checks_run} самопроверок")
